/search.html,{
  "body": "searchkey={{key}}",
  "method": "POST"
}
<js>
let ul = source.getKey() + "/search.html";
headers = {"User-Agent": "Mozilla/5.0 (Linux; Android 9) Mobile Safari/537.36","cookie": "HMACCOUNT=3153D3C95B7AE52C"}

let cc = java.post(ul,`searchkey=${key}`,headers).header("Location");
